// @r_peredelkino · genuine ground-level opening between K1/K2.
import * as T from './vendor/three.module.js';
import {complexFootprints as footprint} from './complex-footprints.js?v=community38';
import {subtractReferenceCuts} from './courtyard-reference-layout.js?v=community38';
import {solidContains} from './walk-physics.js?v=community38';
import {smoothWallNormals} from './facade-detail.js?v=community38';
import {applyPaving} from './paving-material.js?v=community38';
const centre=[-14.93175256487212,-48.17638764031765],normal=[.6770565308208835,.7359310117618295],tangent=[normal[1],-normal[0]];
const world=(u,v)=>[centre[0]+tangent[0]*u+normal[0]*v,centre[1]+tangent[1]*u+normal[1]*v];
let outerDistance=1;while(outerDistance<26&&solidContains(...world(0,-outerDistance),footprint.podium))outerDistance+=.25;
const halfWidth=1.6,inside=1.1,outside=outerDistance+.65,cut=[world(-halfWidth,-outside),world(halfWidth,-outside),world(halfWidth,inside),world(-halfWidth,inside)];
export const courtyardPassage=Object.freeze({id:'k1-k2-promenade',centre,normal,tangent,width:halfWidth*2,clearHeight:2.78,inside,outside,cut,
 source:{node:'node3',view:{pan:-4,tilt:-38,fov:35,size:[1440,1080]},observedPixel:[843,317],rawGround:[-17.050978886695336,-50.47989451186463],registeredTo:'existing inner podium wall',registrationDisplacement:3.130058164055823,dimensions:'Estimated from rendered opening; no working drawing available'},
 route:[world(0,4.0),world(0,.1),world(0,-outside-3.0)]});
const local=([x,z])=>[(x-centre[0])*tangent[0]+(z-centre[1])*tangent[1],(x-centre[0])*normal[0]+(z-centre[1])*normal[1]];
export function insideCourtyardPassage(x,z,margin=0){const [u,v]=local([x,z]);return Math.abs(u)<halfWidth+margin&&v>-outside-margin&&v<inside+margin;}
function interval(a,b,margin=0){const p=local(a),q=local(b),limits=[[-halfWidth-margin,halfWidth+margin],[-outside-margin,inside+margin]];let lo=0,hi=1;for(let k=0;k<2;k++){const d=q[k]-p[k],[min,max]=limits[k];if(Math.abs(d)<1e-12){if(p[k]<min||p[k]>max)return null;continue;}let x=(min-p[k])/d,y=(max-p[k])/d;if(x>y)[x,y]=[y,x];lo=Math.max(lo,x);hi=Math.min(hi,y);if(lo>hi)return null;}return[lo,hi];}
export function splitPassageSegment(a,b,margin=0){const hit=interval(a,b,margin);if(!hit)return{outside:[[a,b]],inside:[]};const [lo,hi]=hit,p=t=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t],outside=[];if(lo>1e-8)outside.push([a,p(lo)]);if(hi<1-1e-8)outside.push([p(hi),b]);return{outside,inside:hi-lo>1e-8?[[p(lo),p(hi)]]:[]};}
const cache=new WeakMap();
export function passageGroundSolids(data=footprint.podium){if(!cache.has(data))cache.set(data,subtractReferenceCuts(data,[cut]).map(s=>({outer:s.outer,holes:s.holes??[],passage: courtyardPassage.id})));return cache.get(data);}
function extrude(data,height,base=0){const shape=new T.Shape(data.outer.map(([x,z])=>new T.Vector2(x,-z)));for(const h of data.holes??[])shape.holes.push(new T.Path(h.map(([x,z])=>new T.Vector2(x,-z))));const g=new T.ExtrudeGeometry(shape,{depth:height,bevelEnabled:false,curveSegments:32});g.rotateX(-Math.PI/2);g.translate(0,base,0);return smoothWallNormals(g);}
function merge(gs){const ns=gs.map(g=>g.index?g.toNonIndexed():g),out=new T.BufferGeometry();for(const key of ['position','normal','uv']){const size=ns.reduce((n,g)=>n+g.attributes[key].array.length,0),data=new Float32Array(size);let offset=0;for(const g of ns){data.set(g.attributes[key].array,offset);offset+=g.attributes[key].array.length;}out.setAttribute(key,new T.BufferAttribute(data,key==='uv'?2:3));}ns.forEach((g,i)=>{if(g!==gs[i])g.dispose();gs[i].dispose();});out.computeBoundingBox();out.computeBoundingSphere();return out;}
export function createGroundPodiumGeometry(depth){const h=Math.min(depth,courtyardPassage.clearHeight),parts=passageGroundSolids().map(p=>extrude(p,h));if(depth>h)parts.push(extrude(footprint.podium,depth-h,h));const g=merge(parts);g.userData.courtyardPassage={...courtyardPassage,depth};return g;}
export function splitGroundPane(pane){const c=Math.cos(pane.angle),s=Math.sin(pane.angle),a=[pane.x-c*pane.width/2,pane.z+s*pane.width/2],b=[pane.x+c*pane.width/2,pane.z-s*pane.width/2];return splitPassageSegment(a,b,.055).outside.map(([a,b])=>({...pane,x:(a[0]+b[0])/2,z:(a[1]+b[1])/2,width:Math.hypot(b[0]-a[0],b[1]-a[1]),passageClipped:true})).filter(p=>p.width>.1);}
export function createCourtyardPassage(root){const group=new T.Group();group.name='Open K1–K2 passage from the courtyard to the promenade';group.userData.passage=courtyardPassage;root.add(group);const material=new T.MeshStandardMaterial({color:0xc2c3bc,roughness:.86});applyPaving(material);const floor=new T.Mesh(extrude({outer:cut,holes:[]},.025,-.014),material);floor.name='Continuous level paving through K1–K2';floor.receiveShadow=true;group.add(floor);const colliders=[];for(const u of [-halfWidth,halfWidth])colliders.push({type:'segment',a:world(u,-outside+.6),b:world(u,inside-.6),radius:.025,source:courtyardPassage.id});return{group,data:courtyardPassage,solids:passageGroundSolids(),colliders,destination:{name:'Проход 1–2',point:world(0,3.7),look:world(0,-outside),originalArea:'courtyard'},dispose(){floor.geometry.dispose();material.dispose();root.remove(group);}};}
